real_css.content:
#world.active .v366-feature.boss.v6115-boss-open{
  cursor:pointer!important;
}
#world.active .v366-feature.boss.v6115-boss-open:active{
  transform:translateY(1px);
}

.v105-rewards{
  margin-top:12px;
  padding:11px;
  border:1px solid #4a5739;
  border-radius:12px;
  background:#11170e;
}
.v105-reward-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:8px;
}
.v105-reward-note{
  margin-top:8px;
  font-size:8px;
  color:#9eaa99;
  line-height:1.4;
}

.v127-daily-reset-note{
  margin-top:7px;
  padding:5px 8px;
  border:1px solid #285d61;
  border-radius:8px;
  background:#091517;
  color:#83cfcd;
  font-size:7px;
  line-height:1.35;
}

/* V4.02: obsolete UI must never become visible again. */
#resetBtn,
.bottom,
#world > .world-hero,
#world > .world-grid{
  display:none !important;
}

/* ===== V4.02 Quest reward stability ===== */
#v231QuestReward{
  z-index:2147483640!important;
}
.v235-loot-harz{
  border-color:#3d7b49!important;
  color:#9bea77!important;
  box-shadow:inset 0 0 12px rgba(104,218,78,.08)!important;
}

.v250-key-hint{
  margin-top:6px;
  padding:6px 7px;
  border:1px solid #5e5330;
  border-radius:8px;
  background:#151207;
  color:#e6cb72;
}

#v123ItemDetail .v297-mystic-detail{
  border-color:rgba(74,227,219,.45)!important;
  background:rgba(28,119,115,.12)!important;
}
#v123ItemDetail .v297-mystic-detail b,
#v123ItemDetail .v297-mystic-detail div{
  color:#8ffff5!important;
}

#questList .v306-first-daily-harz{
 margin-top:5px;padding:5px 7px;border:1px solid #477f3d;border-radius:8px;
 background:#0b1a0d;color:#9ee986;font-size:7px;font-weight:900
}

.v320-point-info{
 margin:7px 0 8px;padding:7px 8px;border-radius:8px;
 background:#0d170f;border:1px solid #284b31;color:#d9eadc;
 font-size:12px;line-height:1.4
}
.v320-point-info b{color:#9cf0ae}
.v320-next{color:#f0d777;margin-top:3px}
.v320-max{color:#8fe6a0;margin-top:3px}

#questList .v321-dampf-level{
 margin-top:5px;padding:5px 7px;border:1px solid #31573a;border-radius:7px;
 background:#0b160e;color:#9cdca4;font-size:6.5px;font-weight:900
}
#questList .v310-elite-reward b{color:#ffd0cb}

#v337LegalFooter{
  margin:28px auto 12px;
  padding:14px 16px;
  max-width:1100px;
  text-align:center;
  font-size:12px;
  line-height:1.5;
  opacity:.78;
}
#v337LegalFooter a{
  text-decoration:underline;
  cursor:pointer;
}

[data-v341-harz-menu]{
  display:flex!important;
  align-items:center;
  gap:8px;
}

/* V4.02 is useful for quest/EXP labels, but never inside the event cards themselves. */
.v366-event .v095-xp2,
.v349-event .v095-xp2{
  display:none!important;
}
.v366-event .v095-xp-text-active,
.v349-event .v095-xp-text-active{
  text-shadow:inherit!important;
}

#world.active .v366-attrs{
  gap:4px!important;
}
#world.active .v366-attr{
  min-height:14px;
}

/* Keep only the main V4.02 quest location banner at the very top. */
#quests > .v038-location{
  display:none!important;
}
#quests .hero-card .tavern-scene .scene-label{
  display:none!important;
}

/* One final artwork owner. Historical renderers may remain for compatibility,
   but every actual item image is now fed from the approved V4.106 comic set. */
.v466-item-art{object-fit:contain!important;display:block!important}

/* XP event decoration must never turn guild upgrade labels into fake x2 bonuses. */
#guild .v095-xp2{display:none!important}
#guild .v095-xp-text-active{color:inherit!important;text-shadow:inherit!important}

.app > header .v358-logo::after{content:"V4.120"!important}
.app > header .v366-ver::after,.app > header .v371-logo em::after,.app > header .v372-logo em::after{content:"V4.120"!important}
#systemtech .v4107-version{color:#9af46f!important}

.app > header .v358-logo::after{content:"V4.127"!important}
.app > header .v366-ver::after,.app > header .v371-logo em::after,.app > header .v372-logo em::after{content:"V4.127"!important}
#quests .v394-skip-row[data-v4127-skip-row="1"]{display:grid!important}

.app > header .v358-logo::after{content:"V4.159"!important}
.app > header .v366-ver::after,.app > header .v371-logo em::after,.app > header .v372-logo em::after{content:"V4.159"!important}
#v200CharacterModal #v4135RetrySave{width:100%;margin-top:10px}

.app > header .v358-logo::after{content:"V4.159"!important}
.app > header .v366-ver::after,.app > header .v371-logo em::after,.app > header .v372-logo em::after{content:"V4.159"!important}
#v200CharacterModal #v4136RetrySave{width:100%;margin-top:10px}

html:not(.v4142-systemtech-admin) #v4104QaRow,
html:not(.v4142-systemtech-admin) #v032MenuPanel [data-screen="systemtech"],
html:not(.v4142-systemtech-admin) #v4102QaButton{display:none!important}

#v032MenuPanel{
  max-height:calc(100vh - 76px)!important;
  overflow-y:auto!important;
  overscroll-behavior:contain;
  scrollbar-width:thin;
}
#v032MenuPanel .v4148-menu-separator{
  height:1px;margin:7px 5px;background:linear-gradient(90deg,transparent,#405c42,transparent);opacity:.9
}

/* Home only: move Kampfkraft slightly upward so the fixed attribute panel never covers it. */
#world.active .v366-power{
  position:relative!important;
  top:-10px!important;
  z-index:5!important;
}
@media(max-width:390px){
  #world.active .v366-power{top:-9px!important;}
}

/* Home only: keep the EXP line clean and place combat power a touch lower. */
#world.active .v366-xptxt > .v095-xp2{display:none!important;}
#world.active .v366-power{top:96px!important;}
@media(max-width:390px){
  #world.active .v366-power{top:91px!important;}
}

#grow .v492-scene,#grow .v492-plant{backface-visibility:hidden;-webkit-backface-visibility:hidden}
#grow .v492-plant{-webkit-tap-highlight-color:transparent}
#grow .v492-plant.selected{transform:none!important}

#dungeonMapCard.v432-d7 .v261-node.boss .v261-bossart{
  inset:3px!important;
  background-size:cover!important;
  background-position:center!important;
  background-repeat:no-repeat!important;
  filter:saturate(1.10) contrast(1.05)!important;
}

.app > header .v358-logo::after{content:"V4.68"!important}
#character #inventory .v459-inv-icon{contain:content!important}
#character #inventory .v459-inv-icon > .v466-item-art{display:block!important;width:43px!important;height:43px!important;margin:auto!important}

html.v495-level-syncing .v101-levelup,
html.v495-level-syncing .v102-levelup-overlay,
html.v495-level-syncing #v420LevelUpOverlay{
  display:none!important;
  visibility:hidden!important;
  opacity:0!important;
  pointer-events:none!important;
}

#v6109MusicRow .v6109-music-note{
  color:#83e56a;
  font-weight:900;
}

.app > header .v358-logo::after{content:"V4.168"!important}
.app > header .v366-ver::after,
.app > header .v371-logo em::after,
.app > header .v372-logo em::after,
#v372TopbarShell .v372-logo em::after{content:"V4.168"!important}

#grow .v492-bottom{
  grid-template-columns:1fr!important;
}
#grow .v492-bottom>.v492-card{
  width:100%!important;
}

/* Safety net: summoner companions must never survive on a non-summoner account. */
body:not(.v6291-summoner-active) .v6287-summon-roster,
body:not(.v6291-summoner-active) .v6287-summon-fx{
  display:none!important;
}

#v260DailyBossArena.v6204-test-mode:after,
#v260DailyBossArena.v6204-test-mode::after{
  display:none!important;
  content:none!important;
  opacity:0!important;
  visibility:hidden!important;
  pointer-events:none!important;
}

/* Keep the working Android status-bar safe area from V6.50, but pull the
   game canvas slightly upward so there is no oversized black band below HUD. */
body.v650-native-safe > .app{
  margin-top:-22px!important;
}

/* Elite-Fenster direkt vor der normalen Questliste */
#quests .v4172-elite-info{
  order:0!important;
  margin:0!important;
}
#quests .v386-list{
  order:1!important;
}
#quests .v387-refresh{
  order:2!important;
}

#v686PetAlbumOverlay .v686-page{contain:layout paint style}
#v686PetAlbumOverlay .v686-pet-row{contain:layout paint style}
#v686PetAlbumOverlay .v686-qbox img,#v686PetAlbumOverlay .v686-pet-pic img{will-change:auto}

/* Historical referral outline is permanently retired; only PNG frame assets render. */
body.v7129-referral-frame #character #v510HeroRoot .avatar-scene,
body.v7129-referral-frame #world .v366-avatar{box-shadow:none!important;outline:none!important}

html:not(.v7260-bag-admin) #bagDealer,
html:not(.v7260-bag-admin) #v032MenuPanel [data-screen="bagDealer"]{
  display:none!important;
}
